import {test,expect,type Page,type TestInfo} from '@playwright/test';
import fs from 'node:fs';
import {demoCatalog} from '../../src/demo.ts';
import {advance} from '../../src/full/engine.ts';
import {driver} from '../../tests/full-route.mjs';
import {snapshot,useJourneyClock,revealStoryChoice} from './support';
// Only the exact historical compatibility declaration below retains its old viewport changes.
// The idle config excludes that declaration; ordinary demo behavior stays at 1440 by 900.
test.use({viewport:{width:1440,height:900},actionTimeout:8000,navigationTimeout:15000});
const clocks=new WeakSet<Page>(),pageErrors=new WeakMap<Page,string[]>();
function listen(page:Page){if(pageErrors.has(page))return;const rows:string[]=[];pageErrors.set(page,rows);page.on('pageerror',e=>rows.push(e.message));}
test.beforeEach(async({page})=>listen(page));
test.afterEach(async({context},info)=>{for(const page of context.pages())if(!page.isClosed()){await info.attach('demo-console-'+context.pages().indexOf(page),{body:JSON.stringify(pageErrors.get(page)??[]),contentType:'application/json'});expect(pageErrors.get(page)??[]).toEqual([]);}});
async function clock(page:Page){listen(page);if(!clocks.has(page)){await useJourneyClock(page);clocks.add(page);}}
async function databases(page:Page){return page.evaluate(()=>indexedDB.databases());}
async function raw(page:Page,name:string){return page.evaluate(name=>new Promise<any>((resolve,reject)=>{const r=indexedDB.open(name);r.onupgradeneeded=()=>{r.transaction!.abort();reject(new Error('Readonly demo observation cannot create '+name));};r.onerror=()=>reject(r.error);r.onsuccess=()=>{const db=r.result,tx=db.transaction([...db.objectStoreNames],'readonly'),out:any={};for(const name of db.objectStoreNames){const s=tx.objectStore(name),keys=s.getAllKeys(),values=s.getAll();values.onsuccess=()=>out[name]={keys:keys.result,values:values.result};}tx.oncomplete=()=>{db.close();resolve(out);};tx.onabort=()=>{db.close();reject(tx.error);};};}),name);}
async function demoDatabase(page:Page){const id=new URL(page.url()).searchParams.get('demo')!,db=(await databases(page)).find(d=>d.name?.startsWith('chenyuan-demo-game-v1-')&&d.name.endsWith('-'+id));return db?.name??null;}
function stored(raw:any,key:string){const i=raw['full-state'].keys.indexOf(key);return i<0?null:raw['full-state'].values[i];}
async function demoGame(page:Page){const name=await demoDatabase(page);return name?stored(await raw(page,name),'current'):null;}
async function demoActivity(page:Page){const name=await demoDatabase(page);return name?stored(await raw(page,name),'activity'):null;}
async function finishControl(page:Page){await expect(page.getByTestId('action-execution')).toBeVisible();await page.clock.runFor(600);await expect(page.getByTestId('save-status')).toHaveText('已保存');}
async function settledControlOrRead(page:Page){await expect.poll(async()=>await page.getByTestId('action-execution').isVisible()?'control':await page.getByTestId('save-status').textContent()==='已保存'?'read':'waiting').not.toBe('waiting');if(await page.getByTestId('action-execution').isVisible())await finishControl(page);else await expect(page.getByTestId('save-status')).toHaveText('已保存');}
async function settings(page:Page){if(!await page.getByRole('dialog',{name:'行旅设置',exact:true}).isVisible())await page.getByRole('button',{name:'设置',exact:true}).click();await expect(page.getByRole('dialog',{name:'行旅设置',exact:true})).toBeVisible();const panel=page.getByTestId('local-records-panel');if(await panel.evaluate(n=>(n as HTMLDetailsElement).open))await panel.locator(':scope>summary').click();}
async function closeSettings(page:Page){if(await page.getByRole('dialog',{name:'行旅设置',exact:true}).isVisible())await page.getByRole('button',{name:'关闭设置',exact:true}).click();}
const normalized=(game:any)=>{const g=structuredClone(game);g.core.runId='<run>';g.core.revision=0;if(g.core.activeEvent)g.core.activeEvent.instanceId='<run>:'+g.core.activeEvent.id;return g;};
async function evidence(info:TestInfo,name:string,value:unknown){const path=info.outputPath(name+'.json');fs.writeFileSync(path,JSON.stringify(value,null,2)+'\n');await info.attach(name,{path,contentType:'application/json'});}
async function loaded(page:Page,id:string){await clock(page);await page.goto('./?demo='+id);await settledControlOrRead(page);await expect(page.getByTestId('demo-persistent-label')).toContainText('演示存档');await expect(page.locator('[data-session]')).toHaveAttribute('data-session','demo');const game=await demoGame(page),source=JSON.parse(fs.readFileSync('public/demo-nodes/'+id+'.json','utf8'));expect(normalized(game)).toEqual(normalized(source.game));return game;}
async function normalFixture(page:Page){await clock(page);await page.goto('/');await expect(page.getByTestId('save-status')).toHaveText('尚无存档',{timeout:15000});await settings(page);await expect(page.getByLabel('文字大小')).toBeEnabled();const panel=page.getByTestId('local-records-panel');if(!await panel.evaluate(n=>(n as HTMLDetailsElement).open))await panel.locator(':scope>summary').click();await page.getByTestId('local-view-overview').click();await expect(page.getByTestId('local-recording')).toBeEnabled();if(!await page.getByTestId('local-recording').isChecked())await page.getByTestId('local-recording').check();await closeSettings(page);const lawful=driver('leave','sword').game;await page.getByLabel('导入已有存档',{exact:true}).setInputFiles({name:'legal-normal-demo-isolation-fixture.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(lawful))});await finishControl(page);const game=await snapshot(page);expect(normalized(game)).toEqual(normalized(lawful));await expect.poll(async()=>{const data=await raw(page,'chenyuan-local-experience-v1');return data.events.values.some((r:any)=>r.data.observation.kind==='import'&&r.data.observation.runId===game.core.runId);}).toBe(true);return{fixture:'formal driver via public import, not a normal earning-route proof',game,normal:await raw(page,'chenyuan-playable-v1'),local:await raw(page,'chenyuan-local-experience-v1'),tracking:await page.evaluate(()=>localStorage.getItem('chenyuan-tracked-goal-v1'))};}
async function unchangedNormal(page:Page,before:any){expect(await raw(page,'chenyuan-playable-v1')).toEqual(before.normal);expect(await raw(page,'chenyuan-local-experience-v1')).toEqual(before.local);expect(await page.evaluate(()=>localStorage.getItem('chenyuan-tracked-goal-v1'))).toBe(before.tracking);}
async function trialPreparation(page:Page){await expect.poll(async()=>await page.getByTestId('trial-review-entry').isVisible()?'ready':await page.getByTestId('breakthrough').isVisible()?'open':'waiting').not.toBe('waiting');if(!await page.getByTestId('trial-review-entry').isVisible())await page.getByTestId('breakthrough').click();await expect(page.getByTestId('trial-review-entry')).toBeEnabled();}
async function choice(page:Page,id:string){await revealStoryChoice(page,id);await expect(page.getByTestId(id)).toBeEnabled();}
async function manual(page:Page,move:'attack'|'flee'){const name=(await demoDatabase(page))!,before=await raw(page,name);expect(stored(before,'activity')?.status).not.toBe('running');expect(stored(before,'current').battle).not.toBeNull();if(!await page.getByTestId(move).isVisible())await page.getByTestId('battle-manual-takeover').click();await expect(page.getByTestId('battle-manual-takeover')).toHaveAttribute('aria-pressed','true');await expect(page.getByTestId(move)).toBeEnabled();expect(await raw(page,name)).toEqual(before);}
async function cycle(page:Page,info:TestInfo,label:string,period:number,operation:()=>Promise<unknown>){const before=await demoGame(page);await operation();await expect.poll(async()=>(await demoActivity(page))?.status).toBe('running');const a=await demoActivity(page);expect([6,7]).toContain(a.version);expect(a.cycleMs).toBe(period);await expect(page.locator('[data-testid=training-activity][data-running=true][data-generation="'+a.generation+'"]')).toBeVisible();await expect(page.getByTestId('training-countdown')).toHaveText((period/1000).toFixed(1)+' 秒');const db=(await demoDatabase(page))!,accepted=await raw(page,db);await page.clock.fastForward(period-1);expect(await demoGame(page)).toEqual(before);expect(await raw(page,db)).toEqual(accepted);await page.clock.fastForward(1);await expect.poll(async()=>(await demoActivity(page))?.completedCycles).toBe(a.completedCycles+1);await expect(page.getByTestId('save-status')).toHaveText('已保存');const after=await demoGame(page),saved=await raw(page,db);expect(after).toEqual(advance(before,a.nextCommand));expect(saved['full-receipts'].keys.filter((k:string)=>k===a.runId+':'+a.nextCommand.commandId)).toHaveLength(1);await evidence(info,label,{before,activity:a,accepted,after,saved,periodMs:period,clock:'virtual formal cycle, not real pacing'});return after;}
async function resetNode(page:Page){await settings(page);page.once('dialog',d=>d.accept());await page.getByTestId('restart').click();await finishControl(page);await closeSettings(page);}
for(const node of demoCatalog)test('demo node '+node.id+' loads a lawful playable state in its own database',async({page},info)=>{
 const game=await loaded(page,node.id);expect(game.core.player.name).toBe('演示顾长青');expect(game.school).toBe(node.school);if(node.phase==='battle'){await manual(page,'attack');await expect(page.getByTestId('attack')).toBeEnabled();}if(node.phase==='causal'){await choice(page,'decide-'+(node.id==='causal-help'?'accept':'bargain'));await expect(page.getByTestId('decide-'+(node.id==='causal-help'?'accept':'bargain'))).toBeEnabled();}if(node.phase==='trial')await trialPreparation(page);if(node.phase==='ending'){await choice(page,'ending-depart');await expect(page.getByTestId('ending-depart')).toBeEnabled();}if(node.phase==='opening')await expect(page.getByTestId('leave')).toBeEnabled();expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1'||d.name==='chenyuan-local-experience-v1')).toBe(false);await settings(page);await expect(page.getByTestId('restore-checkpoint')).toBeDisabled();await evidence(info,'lawful-node-'+node.id,{game,raw:await raw(page,(await demoDatabase(page))!)});
});
test('demo menu, actions, settings and return preserve every normal Game, record and tracking value',async({page,context},info)=>{
 const before=await normalFixture(page);await settings(page);await expect(page.getByLabel('文字大小')).toHaveValue('1');await page.getByTestId('reduce-effects').check();await expect(page.getByTestId('local-data-status')).toContainText('设置已保存');const details=page.getByTestId('local-records-panel');if(!await details.evaluate(n=>(n as HTMLDetailsElement).open))await details.locator(':scope>summary').click();await page.getByTestId('local-export-preview').click();await expect(page.getByTestId('local-export-ready')).toBeVisible();await page.getByTestId('local-export-cancel').click();before.local=await raw(page,'chenyuan-local-experience-v1');await settings(page);await page.getByTestId('demo-menu-open').click();await expect(page.locator('#demo-menu-title')).toBeFocused();const link=await page.getByTestId('demo-node-battle-sword').getAttribute('href');await unchangedNormal(page,before);const demo=await context.newPage();listen(demo);try{const first=await loaded(demo,'battle-sword');expect(new URL(link!,page.url()).search).toBe('?demo=battle-sword');await manual(demo,'attack');const after=await cycle(demo,info,'demo-battle-single-turn',3000,()=>demo.getByTestId('attack').click());expect(after).toEqual(advance(first,{type:'BATTLE',move:'attack',commandId:'expected-demo',runId:first.core.runId,expectedRevision:first.core.revision}));await settings(demo);await expect(demo.getByLabel('文字大小')).toHaveValue('1');await expect(demo.getByTestId('reduce-effects')).not.toBeChecked();await demo.getByTestId('reduce-effects').check();await expect(demo.getByTestId('local-data-status')).toContainText('设置已保存');await demo.getByTestId('reduce-effects').uncheck();await expect(demo.getByTestId('local-data-status')).toContainText('设置已保存');await unchangedNormal(page,before);await expect(page.getByTestId('reduce-effects')).toBeChecked();await expect(page.getByLabel('文字大小')).toHaveValue('1');await closeSettings(demo);await demo.getByTestId('demo-normal').click();await expect(demo.getByTestId('realm')).toHaveText('炼气');expect(await snapshot(demo)).toEqual(await snapshot(page));expect(await raw(page,'chenyuan-playable-v1')).toEqual(before.normal);expect(await demo.evaluate(()=>localStorage.getItem('chenyuan-tracked-goal-v1'))).toBe(before.tracking);await evidence(info,'normal-demo-isolation',{before,first,after,returned:await snapshot(demo)});}finally{expect(pageErrors.get(demo)??[]).toEqual([]);await demo.close();}
});
test('demo reload, reset and typed export/import stay separate from normal saves',async({page},info)=>{
 const initial=await loaded(page,'battle-talisman');await manual(page,'attack');const progressed=await cycle(page,info,'typed-demo-one-turn',3000,()=>page.getByTestId('attack').click());expect(progressed.core.revision).toBe(1);const savedRaw=await raw(page,(await demoDatabase(page))!);await page.reload();await expect(page.getByTestId('save-status')).toHaveText('已保存');expect(await demoGame(page)).toEqual(progressed);expect(await raw(page,(await demoDatabase(page))!)).toEqual(savedRaw);await settings(page);const waiting=page.waitForEvent('download');await page.getByRole('button',{name:'导出当前进度',exact:true}).click();const file=await waiting,text=fs.readFileSync((await file.path())!,'utf8'),saved=JSON.parse(text);expect(saved.format).toBe('chenyuan-demo-save');expect(saved.game).toEqual(progressed);await closeSettings(page);await resetNode(page);expect((await demoGame(page)).core.runId).not.toBe(progressed.core.runId);expect(normalized(await demoGame(page))).toEqual(normalized(initial));await settings(page);await expect(page.getByTestId('import')).toBeEnabled();page.once('dialog',d=>d.accept());await page.getByTestId('import').setInputFiles({name:'demo.json',mimeType:'application/json',buffer:Buffer.from(text)});await finishControl(page);await expect(page.getByTestId('settings-save-status')).toHaveText('已保存');expect(normalized(await demoGame(page))).toEqual(normalized(progressed));const before=await demoGame(page),beforeInvalid=await raw(page,(await demoDatabase(page))!);await page.getByTestId('import').setInputFiles({name:'ordinary.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(before))});await expect(page.getByTestId('settings-error')).toContainText('演示存档');expect(await demoGame(page)).toEqual(before);expect(await raw(page,(await demoDatabase(page))!)).toEqual(beforeInvalid);expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1')).toBe(false);await closeSettings(page);await page.getByTestId('demo-normal').click();await expect(page.getByRole('button',{name:'踏入仙途'})).toBeEnabled();await page.getByLabel('导入已有存档',{exact:true}).setInputFiles({name:'demo.json',mimeType:'application/json',buffer:Buffer.from(text)});await finishRejectedControl(page);await expect(page.getByTestId('error')).toBeVisible();await expect(page.getByTestId('realm')).toHaveCount(0);await evidence(info,'typed-demo-boundary',{initial,progressed,saved,beforeInvalid,normalDatabases:await databases(page)});
});
async function finishRejectedControl(page:Page){await expect(page.getByTestId('action-execution')).toBeVisible();await page.clock.runFor(600);await expect(page.getByTestId('error')).toBeVisible();}
test('unknown, ambiguous, damaged and missing demo nodes never open a normal or demo save',async({page},info)=>{
 const observations:any[]=[];for(const query of ['demo=unknown','demo=','demo=opening&demo=battle-sword']){await clock(page);await page.goto('./?'+query);await expect(page.getByRole('heading',{name:'演示节点未打开'})).toBeVisible();expect(await databases(page)).toEqual([]);observations.push({query,databases:await databases(page)});}await page.route('**/demo-nodes/battle-sword.json',route=>route.fulfill({status:200,contentType:'application/json',body:'{}'}));await page.goto('./?demo=battle-sword');await expect(page.getByRole('heading',{name:'演示节点未打开'})).toBeVisible();expect(await databases(page)).toEqual([]);await page.unroute('**/demo-nodes/battle-sword.json');await page.route('**/demo-nodes/battle-sword.json',route=>route.fulfill({status:404,body:''}));await page.goto('./?demo=battle-sword');await expect(page.getByRole('heading',{name:'演示节点未打开'})).toBeVisible();expect(await databases(page)).toEqual([]);await evidence(info,'invalid-demo-scopes',{observations,finalDatabases:await databases(page)});
});
test('a demo seed quota failure keeps the normal database intact and retries one stable import',async({page},info)=>{
 const normal=await normalFixture(page);await page.addInitScript(()=>{const put=IDBObjectStore.prototype.put;let failed=false;(window as any).__demoRejected=[];IDBObjectStore.prototype.put=function(...args:any[]){if(this.transaction.db.name.startsWith('chenyuan-demo-game-')&&this.name==='full-receipts'){
  (window as any).__demoRejected.push({key:args[1],value:structuredClone(args[0]),injected:!failed});if(!failed){failed=true;throw new DOMException('demo quota probe','QuotaExceededError');}}
  return Reflect.apply(put,this,args);};});await page.goto('./?demo=trial-sword');await finishRejectedControl(page);await expect(page.getByTestId('save-status')).toHaveText('保存待确认');await expect(page.getByTestId('retry')).toBeEnabled();expect(await demoGame(page)).toBeNull();await unchangedNormal(page,normal);const name=(await demoDatabase(page))!,failed=await raw(page,name);expect(failed['full-receipts'].keys).toHaveLength(0);await page.getByTestId('retry').click();await finishControl(page);await trialPreparation(page);await unchangedNormal(page,normal);const recovered=await raw(page,name),attempts=await page.evaluate(()=>(window as any).__demoRejected);expect(recovered['full-receipts'].keys).toHaveLength(1);expect(attempts).toHaveLength(2);expect(attempts[0].injected).toBe(true);expect(attempts[1].injected).toBe(false);expect(attempts[1].key).toBe(attempts[0].key);expect(attempts[1].value).toEqual(attempts[0].value);await evidence(info,'demo-seed-quota-original-retry',{normal,failed,recovered,attempts});
});
test('demo storage denial offers an explicit scoped reread without falling back to the normal Game',async({page},info)=>{
 const normal=await normalFixture(page);await page.addInitScript(()=>{const open=IDBFactory.prototype.open;(window as any).__denyDemo=true;IDBFactory.prototype.open=function(name,...args:any[]){if((window as any).__denyDemo&&name.startsWith('chenyuan-demo-game-'))throw new DOMException('demo denied probe','SecurityError');return Reflect.apply(open,this,[name,...args]);};});await page.goto('./?demo=opening');await expect(page.getByTestId('error')).toBeVisible();await expect(page.getByRole('button',{name:'踏入仙途'})).toHaveCount(0);await unchangedNormal(page,normal);expect((await databases(page)).some(d=>d.name?.startsWith('chenyuan-demo-game-v1-'))).toBe(false);await page.evaluate(()=>(window as any).__denyDemo=false);await page.getByTestId('reload-storage').click();await settledControlOrRead(page);await expect(page.getByTestId('leave')).toBeEnabled();await unchangedNormal(page,normal);await evidence(info,'demo-denial-explicit-reread',{normal,scoped:await raw(page,(await demoDatabase(page))!)});
});
test('demo menus and four viewport screenshots retain a visible scope and playable controls at 150 percent',async({page},info)=>{
 for(const [width,height,id,target]of [[1280,720,'opening','leave'],[1440,900,'trial-sword','trial-review-entry'],[1920,1080,'ending-talisman','ending-depart'],[390,844,'battle-sword','attack']]as const){await page.setViewportSize({width,height});await loaded(page,id);const before=await demoGame(page);await settings(page);await page.getByLabel('文字大小').selectOption('1.5');await expect(page.getByTestId('local-data-status')).toContainText('已保存');await page.getByRole('button',{name:'关闭设置'}).click();const button=page.getByTestId(target);await expect(button).toBeEnabled();await button.focus();await expect(button).toBeFocused();expect(await page.evaluate(()=>document.documentElement.scrollWidth)).toBeLessThanOrEqual(width);expect(await demoGame(page)).toEqual(before);const marker=page.getByTestId('demo-persistent-label');await expect(marker).toContainText('演示存档');const box=await marker.boundingBox();expect(box!.y).toBeGreaterThanOrEqual(0);expect(box!.y+box!.height).toBeLessThanOrEqual(height);await page.screenshot({path:info.outputPath('demo-'+width+'.png')});await page.getByRole('button',{name:'切换演示节点',exact:true}).click();await expect(page.locator('#demo-menu-title')).toBeFocused();await expect(page.getByTestId('demo-node-opening')).toBeVisible();await page.keyboard.press('Escape');await expect(page.getByRole('button',{name:'切换演示节点',exact:true})).toBeFocused();}
});

test('two first-load demo tabs share one seed receipt and sync their own committed turn',async({page,context},info)=>{
 const other=await context.newPage();listen(other);try{await Promise.all([clock(page),clock(other)]);await Promise.all([page.goto('./?demo=battle-sword'),other.goto('./?demo=battle-sword')]);for(const tab of[page,other]){await settledControlOrFailedRead(tab);await expect(tab.getByTestId('demo-persistent-label')).toBeVisible();await expect.poll(()=>demoGame(tab)).not.toBeNull();await expect(tab.getByTestId('save-status')).not.toContainText('保存中');if(await tab.getByTestId('save-status').textContent()==='保存待确认'){await expect(tab.getByTestId('error')).toBeVisible();await tab.reload();await expect(tab.getByTestId('save-status')).toHaveText('已保存');}}const before=await demoGame(page);expect(await demoGame(other)).toEqual(before);const db=(await demoDatabase(page))!;expect((await raw(page,db))['full-receipts'].keys).toHaveLength(1);await manual(page,'attack');const after=await cycle(page,info,'shared-demo-turn',3000,()=>page.getByTestId('attack').click());await expect.poll(async()=>(await demoGame(other))?.core.revision).toBe(1);await expect.poll(()=>other.getByTestId('save-status').textContent()).toBe('已保存');expect(await demoGame(other)).toEqual(after);const receipts=(await raw(page,db))['full-receipts'];expect(receipts.values.filter((r:any)=>r.format==='chenyuan-control-receipt')).toHaveLength(1);expect(receipts.values.filter((r:any)=>r.format==='chenyuan-receipt')).toHaveLength(1);expect(receipts.values.filter((r:any)=>r.format==='chenyuan-activity-receipt')).toHaveLength(1);expect((await databases(page)).some(d=>d.name==='chenyuan-playable-v1')).toBe(false);await evidence(info,'shared-seed-and-cycle',{before,after,receipts});}finally{expect(pageErrors.get(other)??[]).toEqual([]);await other.close();}
});
async function settledControlOrFailedRead(page:Page){await expect.poll(async()=>{if(await page.getByTestId('action-execution').isVisible())return'control';const text=await page.getByTestId('save-status').textContent();return text==='已保存'?'read':text==='保存待确认'?'failed-read':'waiting';}).not.toBe('waiting');if(await page.getByTestId('action-execution').isVisible()){await page.clock.runFor(600);await expect(page.getByTestId('save-status')).not.toHaveText('行动中');await expect(page.getByTestId('save-status')).not.toHaveText('保存中');}}
test('demo trial entries create real repeatable complete checkpoints rather than importing invented ones',async({page},info)=>{
